def calculate_total_utilization(task_set):
    total_U = 0
    for task_i in task_set:
        total_U += calculate_task_utilization(task_i)
    return total_U

def is_taskset_schedulable(task_set):
    for task_i in task_set:
        R_i = calculate_response_time(task_i) # Assumes R_i calculation is available
        if not is_task_schedulable(task_i, R_i):
            return False
    return True

def get_higher_priority_tasks(task_i, all_tasks):
    hp_i = set()
    for task_j in all_tasks:
        if task_j.priority > task_i.priority: # Assuming higher number means higher priority
            hp_i.add(task_j)
    return hp_i

def calculate_blocking_time(task_i, all_tasks, resources):
    B_i = 0
    for task_k in all_tasks:
        if task_k.priority < task_i.priority: # Lower priority task
            for resource_x in task_k.accessed_resources:
                if resource_x.ceiling_priority >= task_i.priority:
                    # Max duration task_k holds resource_x
                    B_i = max(B_i, task_k.get_max_resource_hold_time(resource_x))
    return B_i

def get_affected_tasks_basic(task_i, task_j, all_tasks):
    hep_i = get_higher_or_equal_priority_tasks(task_i, all_tasks)
    lp_j = get_lower_priority_tasks(task_j, all_tasks)
    return hep_i.intersection(lp_j)

def get_affected_tasks_extended(task_i, task_j, all_tasks, resources):
    basic_aff_i_j = get_affected_tasks_basic(task_i, task_j, all_tasks)
    blocking_aff_i_j = get_blocking_affected_tasks(task_i, task_j, all_tasks, resources)
    return basic_aff_i_j.union(blocking_aff_i_j)

def calculate_response_time_with_crpd(task_i, all_tasks, get_gamma_ij_func):
    R_i = task_i.C + task_i.B # Initial estimate
    hp_i = get_higher_priority_tasks(task_i, all_tasks)

    while True:
        interference = 0
        for task_j in hp_i:
            gamma_i_j = get_gamma_ij_func(task_i, task_j, all_tasks) # Call specific gamma function
            num_jobs_j_in_Ri = math.ceil((R_i + task_j.J) / task_j.T)
            interference += num_jobs_j_in_Ri * (task_j.C + gamma_i_j)

        R_i_next = task_i.C + task_i.B + interference

        if R_i_next == R_i:
            return R_i
        elif R_i_next > (task_i.D - task_i.J):
            return float('inf')
        R_i = R_i_next

def get_gamma_ecb_only(task_i, task_j, all_tasks, BRT):
    # task_i is pre-empted, task_j is pre-empting
    return BRT * len(task_j.ECB_set)

def get_gamma_ucb_union(task_i, task_j, all_tasks, BRT):
    # task_i is pre-empted, task_j is pre-empting
    aff_i_j = get_affected_tasks_basic(task_i, task_j, all_tasks) # Using Definition 15

    union_ucb_k = set()
    for task_k in aff_i_j:
        union_ucb_k.update(task_k.UCB_set)

    evicted_useful_blocks = union_ucb_k.intersection(task_j.ECB_set)

    return BRT * len(evicted_useful_blocks)

