def calculate_weighted_schedulability(schedulability_results_map):
    # schedulability_results_map: {taskset_id: {'utilization': u_tau, 'is_schedulable': S_y_tau_p}}

    numerator = 0
    denominator = 0

    for taskset_id, data in schedulability_results_map.items():
        u_tau = data['utilization']
        S_y_tau_p = 1 if data['is_schedulable'] else 0

        numerator += u_tau * S_y_tau_p
        denominator += u_tau

    if denominator == 0:
        return 0.0 # Avoid division by zero
    return numerator / denominator
